// === incremental steps (generated by scratchpad/p36c/gen-steps-tests.py) ===

/// One run of an incremental scenario (tsgo execute/incremental): the edits
/// applied before it, its arguments and tsgo's record of its stdout (the
/// tree root as `<ROOT>`), exit code, written files and build info (`None`:
/// unchanged since the previous step).
struct IncrementalStep {
    caption: &'static str,
    edits: &'static [(&'static str, Option<&'static str>)],
    args: &'static [&'static str],
    stdout: &'static str,
    exit: i32,
    written: &'static [&'static str],
    deleted: &'static [&'static str],
    build_info: &'static [(&'static str, Option<&'static str>)],
}

/// tsc -b's status lines carry the local time: `HH:MM:SS AM - ` (plain) or
/// the grey bracketed form (pretty), normalized before comparison.
fn normalize_status_times(text: &str) -> String {
    fn is_time(bytes: &[u8]) -> bool {
        bytes.len() >= 11
            && bytes[..11]
                .iter()
                .enumerate()
                .all(|(index, byte)| match index {
                    2 | 5 => *byte == b':',
                    8 => *byte == b' ',
                    9 => *byte == b'A' || *byte == b'P',
                    10 => *byte == b'M',
                    _ => byte.is_ascii_digit(),
                })
    }
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while !rest.is_empty() {
        let bytes = rest.as_bytes();
        if (out.is_empty() || out.ends_with('\n'))
            && is_time(bytes)
            && rest[11..].starts_with(" - ")
        {
            out.push_str("HH:MM:SS AM");
            rest = &rest[11..];
            continue;
        }
        if rest.starts_with("[\x1b[90m")
            && is_time(&bytes[6..])
            && rest[17..].starts_with("\x1b[0m] ")
        {
            out.push_str("[\x1b[90mHH:MM:SS AM");
            rest = &rest[17..];
            continue;
        }
        let ch = rest.chars().next().expect("non-empty");
        out.push(ch);
        rest = &rest[ch.len_utf8()..];
    }
    out
}

fn incremental_tree_state(
    root: &std::path::Path,
) -> std::collections::BTreeMap<String, (u128, Vec<u8>)> {
    let mut state = std::collections::BTreeMap::new();
    let mut pending = vec![root.to_path_buf()];
    while let Some(directory) = pending.pop() {
        for entry in fs::read_dir(&directory).expect("read the tree") {
            let entry = entry.expect("read the tree entry");
            let path = entry.path();
            if path.is_dir() {
                pending.push(path);
                continue;
            }
            let modified = entry
                .metadata()
                .and_then(|metadata| metadata.modified())
                .expect("file modification time")
                .duration_since(UNIX_EPOCH)
                .expect("modification time after the epoch")
                .as_nanos();
            let relative = path
                .strip_prefix(root)
                .expect("tree member")
                .to_string_lossy()
                .into_owned();
            state.insert(
                relative,
                (modified, fs::read(&path).expect("read the tree member")),
            );
        }
    }
    state
}

fn run_incremental_steps(tree: &TempTree, steps: &[IncrementalStep]) {
    let root = format!("{}/", compiler_current_directory(tree).display());
    let mut expected_build_info: std::collections::BTreeMap<&str, &str> =
        std::collections::BTreeMap::new();
    for (index, step) in steps.iter().enumerate() {
        for (relative, text) in step.edits {
            let path = tree.path(relative);
            match text {
                Some(text) => {
                    if let Some(parent) = path.parent() {
                        fs::create_dir_all(parent).expect("create the edit's directory");
                    }
                    fs::write(&path, text).expect("write the edit");
                }
                None => fs::remove_file(&path).expect("remove the edited file"),
            }
        }
        if !step.edits.is_empty() {
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let before = incremental_tree_state(&tree.root);
        let output = run(tree, step.args);
        let after = incremental_tree_state(&tree.root);
        let written = after
            .iter()
            .filter(|(relative, state)| before.get(*relative) != Some(state))
            .map(|(relative, _)| relative.as_str())
            .collect::<Vec<_>>();
        let deleted = before
            .keys()
            .filter(|relative| !after.contains_key(*relative))
            .map(String::as_str)
            .collect::<Vec<_>>();
        let stdout = normalize_status_times(
            &String::from_utf8_lossy(&output.stdout).replace(root.as_str(), "<ROOT>/"),
        );
        assert_eq!(
            stdout,
            step.stdout,
            "step {index} ({}) stdout; stderr: {}",
            step.caption,
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(
            output.status.code(),
            Some(step.exit),
            "step {index} ({}) exit",
            step.caption
        );
        assert_eq!(
            written, step.written,
            "step {index} ({}) written files",
            step.caption
        );
        assert_eq!(
            deleted, step.deleted,
            "step {index} ({}) deleted files",
            step.caption
        );
        for (relative, text) in step.build_info {
            if let Some(text) = text {
                expected_build_info.insert(relative, text);
            }
            let expected = expected_build_info
                .get(relative)
                .copied()
                .expect("a build info expectation precedes its reuse");
            assert_eq!(
                fs::read_to_string(tree.path(relative)).expect("read the build info"),
                expected,
                "step {index} ({}) build info {relative}",
                step.caption
            );
        }
    }
}

